/* leak.c */
#include <mcheck.h>
#include <stdlib.h>
int main(void) {
    mtrace();                 /* call first, never muntrace() */
    void *p = malloc(100);
    p = realloc(p, 200);
    malloc(16);               /* leaked */
    free(p);
    return 0;
}

cc -g leak.c -o leak
MALLOC_TRACE=/tmp/t LD_PRELOAD=libc_malloc_debug.so.0 ./leak
mtrace ./leak /tmp/t        # Perl script: symbolizes and reports leaks
